#if UNITY_EDITOR
using System;using System.Linq;using NUnit.Framework;using SporeGobbo.Geometry;using UnityEngine;
public sealed class Stage62BTests
{
 [Test]public void UnreadyStoryViewCannotAcquireOrChangeCamera(){var go=new GameObject("synthetic view");var owner=new GameObject("synthetic owner");try{var view=go.AddComponent<SporeGobbo.Geometry.Preview.WorldRegionPresentation>();Assert.IsFalse(view.CanFrameStory);Assert.IsFalse(view.TryBeginStory(owner,owner.transform,Vector3.zero));view.SetStoryZoom(owner,.6f);Assert.AreEqual(1,view.StoryZoom);view.EndStory(owner);Assert.AreEqual(1,view.StoryZoom);}finally{UnityEngine.Object.DestroyImmediate(owner);UnityEngine.Object.DestroyImmediate(go);}}
 [Test]public void ExistingMushRulesAndLegacyMarkerSurviveAdaptation(){Assert.IsFalse(MushWormIntroEligibility.IsEligible(1,null,true));Assert.IsFalse(MushWormIntroEligibility.IsEligible(2,null,false));var old=new PersistentTestCaveLayout.AuthoredEventLocation{markerKey=MushWormIntroRuntime.MarkerKey,actorCell=new Vector2Int(1,2),focusCell=new Vector2Int(3,4),triggerCell=new Vector2Int(5,6),cameraZoomMultiplier=.82f};var next=RegionStoryLocation.Legacy(old);Assert.AreEqual(old.markerKey,next.markerKey);Assert.AreEqual(old.actorCell,next.actorCell);Assert.AreEqual(old.focusCell,next.focusCell);Assert.AreEqual(old.triggerCell,next.triggerCell);Assert.AreEqual(old.cameraZoomMultiplier,next.cameraZoomMultiplier);}
 [Test]public void AuthoredShinyUsesTheRealLegacyPickupConfiguration(){var go=new GameObject("synthetic shiny");try{RunContentSpawner.EnsureShinyPickup(go);RunContentSpawner.EnsureShinyPickup(go);Assert.AreEqual(1,go.GetComponents<CollectibleShiny>().Length);Assert.AreEqual(1,go.GetComponents<CircleCollider2D>().Length);Assert.IsTrue(go.GetComponent<CircleCollider2D>().isTrigger);Assert.AreEqual(.5f,go.GetComponent<CircleCollider2D>().radius);}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test]public void RetreatSceneReferenceIsTheRealPortalRootNotItsPromptCanvas(){var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ReturnPortal.prefab");Assert.IsNotNull(prefab.GetComponent<RunRetreatPortal>());UnityEditor.AssetDatabase.TryGetGUIDAndLocalFileIdentifier(prefab,out string guid,out long id);string scene=System.IO.File.ReadAllText(Application.dataPath+"/Expedition/FirstExpedition.unity");StringAssert.Contains("retreatPrefab: {fileID: "+id+", guid: "+guid,scene);}
 sealed class Wall:ICompleteTerrainDefinition{public bool Protected(int x,int y)=>x<1||y<1||x>30||y>30;public bool TrySolid(int x,int y,out bool s){s=x==16;return true;}}
 [Test]public void ExcavationOpensRoutesAndStaleTransactionsReject(){var state=new RegionTerrainState("test",32,32,new Wall());var a=new Point2(12.5,16.5);var b=new Point2(20.5,16.5);Assert.AreEqual(0,state.Route(a,b,3).Count);var commit=state.TakeMutationControl();Assert.AreEqual(1,commit(new[]{new DualTile(16,16)},0,c=>true));Assert.Greater(state.Route(a,b,1).Count,0);Assert.AreEqual(0,state.Route(a,b,3).Count,"one-cell gap must not carry three-cell body");Assert.AreEqual(0,commit(new[]{new DualTile(16,15)},0,c=>true),"stale revision");Assert.AreEqual(2,commit(new[]{new DualTile(16,15),new DualTile(16,17)},1,c=>true));Assert.Greater(state.Route(a,b,3).Count,0);}
 [Test]public void WalkableRootArchHasARealThreeCellUnderpass(){var d=new ExpeditionLayout();var state=new RegionTerrainState("test",144,128,d);Assert.IsTrue(state.Fits(new Point2(78.5,68.5),3));Assert.Greater(state.Route(new Point2(68.5,68.5),new Point2(87.5,64.5),3).Count,0);}
 [Test]public void SharedGridRoundTripsAtExpeditionDimensions(){var grid=new LogicalGridTransform(default,.6,128);foreach(var p in new[]{new Point2(20.5,100.5),new Point2(113.5,64.5)}){var q=grid.ToLogical(grid.ToWorld(p));Assert.AreEqual(p.X,q.X,1e-8);Assert.AreEqual(p.Y,q.Y,1e-8);}}
 [Test]public void ConcealedUnitsHaveRealPhysicalSeals(){var d=new ExpeditionLayout();var w=new StreamingWorld(144,128,62001,d);var seen=new System.Collections.Generic.HashSet<int>();var queue=new System.Collections.Generic.Queue<int>();int start=100*144+20;seen.Add(start);queue.Enqueue(start);while(queue.Count>0){int i=queue.Dequeue();foreach(int n in new[]{i-1,i+1,i-144,i+144})if(n>=0&&n<144*128&&!w.IsSolid(n%144,n/144)&&seen.Add(n))queue.Enqueue(n);}foreach(var group in d.Concealed)Assert.IsFalse(group.Cells.Any(seen.Contains),group.Id+" must require real excavation, not only a visual gate");}
 [Test]public void AuthoredDefinitionIsCompleteDeterministicAndBounded(){var a=new ExpeditionLayout();var b=new ExpeditionLayout();Assert.AreEqual(a.Fingerprint(),b.Fingerprint());var w=new StreamingWorld(144,128,62001,a);for(int y=0;y<128;y++)for(int x=0;x<144;x++){Assert.IsTrue(a.TrySolid(x,y,out var s));Assert.AreEqual(a.Protected(x,y)||s,w.IsSolid(x,y));}}
 [Test]public void RequiredAnchorsAreConnectedAtThreeCellClearance(){var d=new ExpeditionLayout();var s=new RegionTerrainState("expedition",144,128,d);foreach(var p in d.Anchors){Assert.IsTrue(s.Fits(p.Value,3),p.Key);Assert.Greater(s.Route(d.Anchors["arrival"],p.Value,3).Count,0,p.Key);}}
 [Test]public void PermanentLandmarkMasksRejectExcavation(){var d=new ExpeditionLayout();var s=new RegionTerrainState("expedition",144,128,d);var commit=s.TakeMutationControl();foreach(var f in d.Footprints.Values)Assert.AreEqual(0,commit(f,s.Revision,c=>true));Assert.AreEqual(0,s.Revision);}
 [Test]public void DiscoveryNeverChangesPhysicalOccupancy(){var d=new ExpeditionLayout();var w=new StreamingWorld(144,128,62001,d);using(var discovery=new CaveDiscovery(w,new DiscoveryIndex(w,d.Concealed))){discovery.SeedKnown(d.InitialKnown);foreach(var hidden in d.Concealed){Assert.Greater(hidden.Cells.Length,0,hidden.Id);foreach(int i in hidden.Cells){Assert.IsFalse(w.IsSolid(i%144,i/144));Assert.IsFalse(discovery.Shown(i%144,i/144));}}int revision=w.Revision;discovery.Explore(d.Anchors["arrival"]);discovery.Tick(2);Assert.AreEqual(revision,w.Revision);}}
 [Test]public void MissingTerrainCannotGrantLineOfSight(){if(DiggableTerrainService.Active==null&&MapGenerator.Instance==null)Assert.IsFalse(MapPathfinder.HasLineOfWalkableSight(Vector2.zero,Vector2.one));}
 [Test]public void ResistanceFixturesAreOptionalAndDoNotChangeCampaign(){var d=new ExpeditionLayout();Assert.AreEqual(1,d.Resistance(80,106));Assert.AreEqual(2,d.Resistance(86,106));Assert.AreEqual(3,d.Resistance(91,106));Assert.AreEqual(1,d.Resistance(68,92));}
}
#endif
